    ('treatment_sessions','treatment_sessions_organization_id_fkey','FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE CASCADE'),
    ('treatment_sessions','treatment_sessions_package_id_fkey','FOREIGN KEY (package_id) REFERENCES patient_packages(id)'),
    ('treatment_sessions','treatment_sessions_patient_id_fkey','FOREIGN KEY (patient_id) REFERENCES patients(id) ON DELETE CASCADE'),
    ('treatment_sessions','treatment_sessions_performed_by_fkey','FOREIGN KEY (performed_by) REFERENCES auth.users(id)'),
    ('treatment_sessions','treatment_sessions_sales_invoice_item_id_fkey','FOREIGN KEY (sales_invoice_item_id) REFERENCES sales_invoice_items(id) ON DELETE SET NULL'),
    ('vital_sign_requests','vital_sign_requests_branch_id_fkey','FOREIGN KEY (branch_id) REFERENCES branches(id)'),
    ('vital_sign_requests','vital_sign_requests_doctor_id_fkey','FOREIGN KEY (doctor_id) REFERENCES doctors(id)'),
    ('vital_sign_requests','vital_sign_requests_organization_id_fkey','FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE CASCADE'),
    ('vital_sign_requests','vital_sign_requests_patient_id_fkey','FOREIGN KEY (patient_id) REFERENCES patients(id)'),
    ('vital_sign_requests','vital_sign_requests_recorded_by_fkey','FOREIGN KEY (recorded_by) REFERENCES auth.users(id)'),
    ('vital_sign_requests','vital_sign_requests_requested_by_fkey','FOREIGN KEY (requested_by) REFERENCES auth.users(id)'),
    ('vital_sign_requests','vital_sign_requests_visit_id_fkey','FOREIGN KEY (visit_id) REFERENCES patient_visits(id)'),
    ('vital_sign_requests','vital_sign_requests_vital_sign_id_fkey','FOREIGN KEY (vital_sign_id) REFERENCES patient_vital_signs(id)'),
    ('voucher_invoice_allocations','voucher_invoice_allocations_sales_invoice_id_fkey','FOREIGN KEY (sales_invoice_id) REFERENCES sales_invoices(id) ON DELETE CASCADE'),
    ('voucher_invoice_allocations','voucher_invoice_allocations_voucher_id_fkey','FOREIGN KEY (voucher_id) REFERENCES financial_vouchers(id) ON DELETE CASCADE'),
    ('waiting_room_tickers','waiting_room_tickers_created_by_fkey','FOREIGN KEY (created_by) REFERENCES auth.users(id)'),
    ('waiting_room_tickers','waiting_room_tickers_organization_id_fkey','FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE CASCADE'),
    ('warehouse_locations','warehouse_locations_created_by_fkey','FOREIGN KEY (created_by) REFERENCES auth.users(id)'),
    ('warehouse_locations','warehouse_locations_organization_id_fkey','FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE CASCADE'),
    ('warehouse_locations','warehouse_locations_parent_location_id_fkey','FOREIGN KEY (parent_location_id) REFERENCES warehouse_locations(id)'),
    ('warehouse_locations','warehouse_locations_warehouse_id_fkey','FOREIGN KEY (warehouse_id) REFERENCES warehouses(id) ON DELETE CASCADE'),
    ('warehouses','warehouses_branch_id_fkey','FOREIGN KEY (branch_id) REFERENCES branches(id) ON DELETE SET NULL'),
    ('warehouses','warehouses_organization_id_fkey','FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE CASCADE'),
    ('warehouses','warehouses_zatca_company_id_fkey','FOREIGN KEY (zatca_company_id) REFERENCES zatca_companies(id) ON DELETE SET NULL'),
    ('zatca_companies','zatca_companies_organization_id_fkey','FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE CASCADE')
    ) as t(tbl, name, def)
  loop
    -- الجدول غير موجود: ليس شأن هذه الترقية (فحص الفجوات يُبلغ عنه)
    if to_regclass('public.' || r.tbl) is null then
      continue;
    end if;
    if exists (
      select 1 from pg_constraint c
        join pg_class cl on cl.oid = c.conrelid
        join pg_namespace n on n.oid = cl.relnamespace
       where n.nspname = 'public' and cl.relname = r.tbl and c.conname = r.name
    ) then
      continue;
    end if;

    begin
      execute format('alter table public.%I add constraint %I %s', r.tbl, r.name, r.def);
      v_added := v_added + 1;
      raise notice '✅ أُضيف %.%', r.tbl, r.name;
    exception when others then
      v_failed := v_failed + 1;
      raise notice '⚠️ تعذّر %.% — %', r.tbl, r.name, sqlerrm;
    end;
  end loop;

  raise notice '0148: أُضيف % مفتاح ربط، وتعذّر %', v_added, v_failed;
end $$;

-- ---------------------------------------------------------------------------
-- إعادة تحميل ذاكرة المخطّط في PostgREST.
--
-- بلا هذا السطر تبقى الشاشات تُظهر «schema cache» نفسه بعد إضافة المفاتيح،
-- لأن PostgREST يحتفظ بنسخته من الروابط في الذاكرة ولا يعيد قراءتها إلّا
-- بإشعار أو بإعادة تشغيل.
-- ---------------------------------------------------------------------------
notify pgrst, 'reload schema';
